SOURCE_SKILL = "tau2Airline"

def _split_name(full):
    parts = (full or "").split(" ", 1)
    return {"first_name": parts[0], "last_name": parts[1] if len(parts) > 1 else ""}

def _normalize_passenger(p):
    dob = p.get("dob") or p.get("date_of_birth") or ""
    return {"first_name": p.get("first_name", ""), "last_name": p.get("last_name", ""), "dob": dob}

def patched_load(cls, path=None):
    conn = sqlite3.connect('world.db')
    conn.row_factory = sqlite3.Row
    try:
        flights = {}
        for r in conn.execute("SELECT * FROM flights WHERE source_skill=?", (SOURCE_SKILL,)):
            raw_dates = json.loads(r["dates_json"] or "{}")
            clean_dates = {}
            for dt_key, dt_val in raw_dates.items():
                if isinstance(dt_val, dict):
                    raw_status = dt_val.get("status", "available")
                    if raw_status not in _VALID_STATUSES:
                        dt_val["status"] = _STATUS_MAP.get(raw_status, "available")
                    for fld in ("prices", "available_seats"):
                        if fld in dt_val and isinstance(dt_val[fld], dict):
                            dt_val[fld] = {k: v for k, v in dt_val[fld].items() if k in _VALID_CABS}
                clean_dates[dt_key] = dt_val
            flights[r["flight_id"]] = {
                "flight_number": r["flight_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "scheduled_departure_time_est": r["departure_time"] or "00:00:00",
                "scheduled_arrival_time_est": r["arrival_time"] or "00:00:00",
                "dates": clean_dates,
            }
        resv_by_user = {}
        reservations = {}
        for r in conn.execute("SELECT * FROM flight_bookings WHERE source_skill=?", (SOURCE_SKILL,)):
            res_flights = []
            for fj in json.loads(r["flights_json"] or "[]"):
                res_flights.append({
                    "flight_number": fj.get("flight_number") or fj.get("flight_id"),
                    "origin": fj.get("origin", ""),
                    "destination": fj.get("destination", ""),
                    "date": fj.get("date", ""),
                    "price": fj.get("price", 0),
                })
            raw_passengers = json.loads(r["passengers_json"] or "[]")
            clean_passengers = [_normalize_passenger(p) for p in raw_passengers]
            reservations[r["booking_id"]] = {
                "reservation_id": r["booking_id"],
                "user_id": r["user_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "flight_type": r["flight_type"] if r["flight_type"] in _TAU2_FLIGHT_TYPES else "one_way",
                "cabin": r["cabin_class"] if r["cabin_class"] in _TAU2_CABINS else "economy",
                "flights": res_flights,
                "passengers": clean_passengers,
                "payment_history": json.loads(r["payment_history_json"] or "[]"),
                "created_at": r["booked_at"],
                "total_baggages": r["total_baggages"],
                "nonfree_baggages": r["nonfree_baggages"],
                "insurance": r["add_insurance"] if r["add_insurance"] in ("yes", "no") else "no",
                "status": "cancelled" if r["status"] == "cancelled" else None,
            }
            resv_by_user.setdefault(r["user_id"], []).append(r["booking_id"])
        users = {}
        for r in conn.execute("SELECT * FROM users WHERE skill_ids_json LIKE ?", ('%"tau2Airline"%',)):
            users[r["user_id"]] = {
                "user_id": r["user_id"],
                "name": _split_name(r["name"]),
                "address": json.loads(r["address_json"] or "{}"),
                "email": r["email"],
                "dob": r["dob"] or "",
                "payment_methods": json.loads(r["payment_methods_json"] or "{}"),
                "saved_passengers": json.loads(r["saved_passengers_json"] or "[]"),
                "membership": _TIER_MAP.get(r["loyalty_tier"], r["loyalty_tier"]),
                "reservations": resv_by_user.get(r["user_id"], []),
            }
    finally:
        conn.close()
    return cls.model_validate({"flights": flights, "users": users, "reservations": reservations})

data_model.FlightDB.load = classmethod(patched_load)
